using Collector=suitecut::NativePrivateResponseSession;using Dict=Collector::Dict;
std::string JSON(Dict value){auto wrapper=CefValue::Create();wrapper->SetDictionary(value->Copy(false));return CefWriteJSON(wrapper,JSON_WRITER_DEFAULT).ToString();}
Dict Parse(const std::string&text){return CefParseJSON(text,JSON_PARSER_RFC)->GetDictionary();}
Dict Actual(const std::string&id,const std::string&type="Other",const std::string&frame="actual-frame",const std::string&loader="actual-loader"){
 auto result=CefDictionaryValue::Create();result->SetString("requestId",id);result->SetString("type",type);result->SetString("frameId",frame);result->SetString("loaderId",loader);return result;
}
struct Harness{
 struct Sent{std::string method;Dict params;double deadline;Collector::Reply callback;};
 std::vector<Sent> sent;double now=1;int fatal=0,ready=0;std::unique_ptr<Collector> collector;
 Harness(){collector=std::make_unique<Collector>([this](const auto&method,Dict params,double deadline,Collector::Reply done){sent.push_back({method,params->Copy(false),deadline,std::move(done)});},[this]{return now;},[]{},[this](const auto&){++fatal;});}
 void ACK(size_t index,const std::string&result){auto done=std::move(sent[index].callback);done(true,result);}
 int ID(size_t index){return Parse(sent[index].params->GetString("message"))->GetInt("id");}
 void InnerReply(int id,const std::string&result){auto message=CefDictionaryValue::Create();message->SetInt("id",id);message->SetDictionary("result",Parse(result));Nested(JSON(message));}
 void Nested(const std::string&message){auto packet=CefDictionaryValue::Create();packet->SetString("targetId","actual-target");packet->SetString("sessionId","actual-private");packet->SetString("message",message);assert(collector->Event("Target.receivedMessageFromTarget",packet));}
 void Event(const std::string&method,Dict actual){auto message=CefDictionaryValue::Create();message->SetString("method",method);message->SetDictionary("params",actual->Copy(false));Nested(JSON(message));}
 void Initialize(){assert(collector->Start(100,[this](bool ok,const auto&){if(ok)++ready;}));ACK(0,R"({"targetInfo":{"type":"page","targetId":"actual-target"}})");auto attached=Parse(R"({"sessionId":"actual-private","targetInfo":{"targetId":"actual-target","type":"page"}})");assert(collector->Event("Target.attachedToTarget",attached));ACK(1,R"({"sessionId":"actual-private"})");assert(sent[2].method=="Target.sendMessageToTarget");auto inner=Parse(sent[2].params->GetString("message"));assert(inner->GetString("method")=="Network.enable");auto settings=inner->GetDictionary("params");assert(settings->GetBool("enableDurableMessages")&&settings->GetInt("maxTotalBufferSize")==8*1048576);ACK(2,"{}");assert(collector->physical()==1&&ready==0);InnerReply(ID(2),"{}");assert(collector->ready()&&ready==1&&collector->physical()==0);}
 void Admit(const std::string&id){auto request=Actual(id);collector->Primary("Network.requestWillBeSent",request);Event("Network.requestWillBeSent",request);collector->Primary("Network.loadingFinished",request);Event("Network.loadingFinished",request);}
 void Detached(){auto packet=CefDictionaryValue::Create();packet->SetString("sessionId","actual-private");assert(collector->Event("Target.detachedFromTarget",packet));}
};
