 h.Admit("mixed-redirect");auto mixed=Actual("mixed-redirect","Script");mixed->SetDictionary("redirectResponse",CefDictionaryValue::Create());h.Event("Network.requestWillBeSent",mixed);assert(!h.collector->Read("mixed-redirect",50,[](bool,const auto&){assert(false);}));
