 {Harness h;h.Initialize();h.Admit("outer-expired");int calls=0;assert(h.collector->Read("outer-expired",5,[&](bool ok,const auto&error){assert(!ok&&error=="Private body original deadline exceeded");++calls;}));h.now=5;h.collector->Tick(5);auto outer=std::move(h.sent[3].callback);outer(false,"Native network command deadline expired");assert(h.collector->physical()==1&&calls==0);h.ACK(4,"{}");assert(h.collector->physical()==1&&calls==0);h.Detached();assert(h.collector->physical()==0&&calls==1);}
 {Harness h;h.Initialize();h.Admit("outer-late-before-tick");int calls=0;assert(h.collector->Read("outer-late-before-tick",5,[&](bool ok,const auto&error){assert(!ok&&error=="Private body original deadline exceeded");++calls;}));h.now=5;auto outer=std::move(h.sent[3].callback);outer(false,"Native network command deadline expired");assert(h.collector->physical()==1&&calls==0);h.InnerReply(h.ID(3),R"({"body":"actual late inner response","base64Encoded":false})");assert(calls==1&&h.collector->physical()==0);h.Detached();}
