 {Harness h;assert(h.collector->Start(5,[](bool ok,const auto&){assert(!ok);}));h.ACK(0,R"({"targetInfo":{"type":"page","targetId":"actual-target"}})");h.now=5;auto attach=std::move(h.sent[1].callback);attach(false,"Native network command deadline expired");assert(h.fatal==1&&Collector::Sessions()==1);auto observed=Parse(R"({"sessionId":"actual-private","targetInfo":{"targetId":"actual-target","type":"page"}})");assert(h.collector->Event("Target.attachedToTarget",observed));assert(h.sent[2].method=="Target.detachFromTarget");h.ACK(2,"{}");assert(Collector::Sessions()==1);h.Detached();assert(Collector::Sessions()==0);}
